package gnark

// poseidon_params.go provides the BN254 Poseidon round constants and matrices
// for the in-circuit optimized gadget.
//
// The concrete values are generated by cmd/gen_poseidon_params and live in
// poseidon_constants_gen.go.  Run:
//
//	cd surcorelibs && go generate ./gnark/
//
// Algorithm: iden3 optimized BN254 Poseidon (Grassi et al. 2019 §3.2)
// Parameters (BN254, matching iden3/go-iden3-crypto v0.0.17):
//   - State width:    t = 3  (rate=2, capacity=1)
//   - Full rounds:    Rf = 8
//   - Partial rounds: Rp = 57
//   - S-box:          x^5
//
// The optimized algorithm differs from "standard" Poseidon in partial rounds:
//   - Standard: each partial round does ARK + partial S-box + full MDS multiply
//   - Optimized: each partial round does partial S-box + scalar ARK + sparse
//     linear transform (S), plus a one-time mix with P at the full-to-partial
//     transition.  Both algorithms produce identical hash outputs.
//
// The in-circuit permutation is implemented in circuit.go (bn254PoseidonPermute).
// The canonical test vector is:
//
//	Poseidon(1, 2) == 0x115cc0f5e7d690413df64c6b9662e9cf2a3617f2743245519e19607a4417189a

import (
	"github.com/consensys/gnark/frontend"
)

// poseidonParams returns the four constant arrays needed by the optimized
// BN254 Poseidon permutation for t=3, Rf=8, Rp=57.
//
// Return values:
//
//	C  [81]frontend.Variable   round constants
//	S  [285]frontend.Variable  sparse partial-round linear layer
//	M  [3][3]frontend.Variable MDS matrix (full rounds + final round)
//	P  [3][3]frontend.Variable transition matrix (full to partial rounds)
func poseidonParams() (
	C [81]frontend.Variable,
	S [285]frontend.Variable,
	M [3][3]frontend.Variable,
	P [3][3]frontend.Variable,
) {
	return bn254PoseidonC(), bn254PoseidonS(), bn254PoseidonMDS(), bn254PoseidonP()
}
